import hashlib
import hmac
import json
import re

from payhook.errors import InvalidNotification

_CURRENCY_RE = re.compile(r"^[A-Z]{3}$")


def _validate_payload(data):
    if not isinstance(data, dict):
        raise InvalidNotification("JSON is not an object")

    event_id = data.get("event_id")
    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("Missing or empty event_id")

    account_id = data.get("account_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("Missing or empty account_id")

    amount_minor = data.get("amount_minor")
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("amount_minor must be a non-negative integer")
    if amount_minor < 0:
        raise InvalidNotification("amount_minor must be non-negative")

    currency = data.get("currency")
    if not isinstance(currency, str) or not _CURRENCY_RE.match(currency):
        raise InvalidNotification("currency must be three uppercase ASCII letters")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""

    # Case-insensitive header lookup
    hdr = {}
    for k, v in headers.items():
        hdr[k.lower()] = v

    # --- Timestamp validation ---
    ts_str = hdr.get("x-pay-timestamp")
    if ts_str is None:
        raise InvalidNotification("Missing X-Pay-Timestamp")
    try:
        ts_val = float(ts_str)
    except (ValueError, TypeError):
        raise InvalidNotification("Malformed X-Pay-Timestamp")

    # Use <= so that NaN/inf are rejected (NaN comparisons are always False)
    if not (abs(ts_val - now) <= 300):
        raise InvalidNotification("Stale timestamp")

    # --- Header values ---
    sig = hdr.get("x-pay-signature", "")
    receipt_hdr = hdr.get("x-pay-receipt", "")

    # --- v1 path: HMAC-SHA256(secret, ascii_ts + "." + raw_body) ---
    if sig.startswith("v1="):
        v1_hex = sig[3:]
        expected = hmac.new(
            secret, ts_str.encode("ascii") + b"." + raw_body, hashlib.sha256
        ).hexdigest()
        if hmac.compare_digest(v1_hex, expected):
            try:
                data = json.loads(raw_body)
            except (json.JSONDecodeError, ValueError):
                raise InvalidNotification("Malformed JSON")
            return _validate_payload(data)

    # --- r0 path: HMAC-SHA256(secret, ascii_ts + "." + utf8_event_id) ---
    if receipt_hdr.startswith("r0="):
        r0_hex = receipt_hdr[3:]
        try:
            data = json.loads(raw_body)
        except (json.JSONDecodeError, ValueError):
            raise InvalidNotification("Malformed JSON")

        if not isinstance(data, dict):
            raise InvalidNotification("JSON is not an object")

        event_id = data.get("event_id")
        if not isinstance(event_id, str) or not event_id:
            raise InvalidNotification("Missing or empty event_id")

        expected_r0 = hmac.new(
            secret,
            ts_str.encode("ascii") + b"." + event_id.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        if hmac.compare_digest(r0_hex, expected_r0):
            return _validate_payload(data)

    raise InvalidNotification("Signature verification failed")
